<?php
declare(strict_types=1);

function tr_json(mixed $v): string {
    $j=json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);
    if($j===false) ingestion_fail('TRANSFERS JSON encoding failed.');
    return $j;
}
function tr_text(mixed $v,int $max=255): ?string {
    if($v===null)return null;$s=trim((string)$v);return $s===''?null:mb_substr($s,0,$max);
}
function tr_uint(mixed $v): ?int {
    if($v===null||$v==='')return null;
    if(!is_int($v)&&!(is_string($v)&&ctype_digit($v)))return null;
    $n=(int)$v;return $n>0?$n:null;
}
function tr_number(mixed $v): int|float|null {
    $s=trim((string)($v??''));if($s===''||!preg_match('/^(\d+(?:[.,]\d+)?)\s*([kKmM])?$/u',$s,$m))return null;
    $n=(float)str_replace(',','.',$m[1]);$u=strtoupper($m[2]??'');if($u==='K')$n*=1000;if($u==='M')$n*=1000000;
    return fmod($n,1.0)===0.0?(int)$n:$n;
}
function tr_cost_number(mixed $v): int|float|null {
    $n=tr_number($v);
    return $n!==null&&$n<=99999999.9999?$n:null;
}
function tr_hash(mixed $v): string {return hash('sha256',is_string($v)?$v:tr_json($v));}
function tr_uuid(): string {$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}
function tr_worlds(): never {ingestion_reply(['ok'=>true,'type'=>'transfers','worlds'=>['GW001','GW002','GW003','GW004','GW005','GW006','GW007','GW008','GW009']]);}
function tr_core_world(string $gw): array {
    $core=smm_db();$q=$core->prepare('SELECT game_world_id,imc_name,game_world_type,sm_game_world_id,soccer_manager_season FROM imc_game_worlds WHERE game_world_id=? LIMIT 1');$q->execute([$gw]);$r=$q->get_result()->fetch_assoc();$q->close();
    if(!$r||$r['sm_game_world_id']===null)ingestion_fail('CORE Game World context unavailable.',409);
    return ['game_world_id'=>$gw,'name'=>(string)$r['imc_name'],'type'=>(string)$r['game_world_type'],'sm_game_world_id'=>(int)$r['sm_game_world_id'],'soccer_manager_season'=>$r['soccer_manager_season']===null?null:(int)$r['soccer_manager_season']];
}
function tr_ensure_world(mysqli $db,array $ctx): void {
    $family=ingestion_storage_key($ctx['game_world_id'])==='gold'?'multi_league':'single_league';
    $q=$db->prepare('INSERT INTO gw_game_worlds(game_world_id,game_world_name,game_world_type,sm_game_world_id,current_soccer_manager_season,created_at,updated_at) VALUES(?,?,?,?,?,NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE game_world_name=VALUES(game_world_name),game_world_type=VALUES(game_world_type),sm_game_world_id=VALUES(sm_game_world_id),current_soccer_manager_season=VALUES(current_soccer_manager_season),updated_at=NOW(6)');
    $q->execute([$ctx['game_world_id'],$ctx['name'],$family,$ctx['sm_game_world_id'],$ctx['soccer_manager_season']]);$q->close();
}
function tr_page_type(mysqli $db): int {
    $q=$db->prepare("INSERT INTO gw_source_page_types(function_description,page_code,page_name,scope_status,url_pattern) VALUES('Soccer Manager all transfers page','P19','All Transfers','CERTIFIED',NULL) ON DUPLICATE KEY UPDATE page_type_id=LAST_INSERT_ID(page_type_id)");$q->execute();$id=(int)$db->insert_id;$q->close();
    if($id<1){$r=$db->query("SELECT page_type_id FROM gw_source_page_types WHERE page_code='P19' LIMIT 1")->fetch_assoc();$id=(int)($r['page_type_id']??0);}if($id<1)ingestion_fail('P19 source page type unavailable.',409);return $id;
}
function tr_start(mysqli $db,array $b,string $gw): never {
    $ctx=tr_core_world($gw);tr_ensure_world($db,$ctx);$uuid=tr_uuid();$version=tr_text($b['version']??null,64)??'TRANSFERS';
    $q=$db->prepare("INSERT INTO gw_import_runs(created_at,game_world_id,parser_version,run_status,run_uuid,sm_game_world_id,source_capture_count,started_at,stats_json) VALUES(NOW(6),?,?,'running',?,?,0,NOW(6),'{}')");$q->execute([$gw,$version,$uuid,$ctx['sm_game_world_id']]);$q->close();
    ingestion_reply(['ok'=>true,'type'=>'transfers','action'=>'start','game_world_id'=>$gw,'importId'=>$uuid,'repository'=>'gw_transfers']);
}
function tr_probe(mysqli $db,array $b,string $gw): never {
    $candidates=$b['candidates']??[];if(!is_array($candidates)||count($candidates)>5000)ingestion_fail('candidates invalid.');
    $count=$db->prepare('SELECT COUNT(*) c FROM gw_transfers WHERE game_world_id=?');$count->execute([$gw]);$rows=(int)$count->get_result()->fetch_assoc()['c'];$count->close();
    $max=$db->prepare("SELECT COALESCE(MAX(CAST(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.imc_transfer_number')) AS UNSIGNED)),0) n FROM gw_source_payloads p JOIN gw_source_captures c ON c.capture_id=p.capture_id WHERE c.game_world_id=? AND c.report_type='TRANSFERS' AND p.payload_type='TRANSFER_EVENT'");$max->execute([$gw]);$maxNumber=(int)$max->get_result()->fetch_assoc()['n'];$max->close();
    $find=$db->prepare("SELECT CAST(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.imc_transfer_number')) AS UNSIGNED) n FROM gw_source_payloads p JOIN gw_source_captures c ON c.capture_id=p.capture_id WHERE c.game_world_id=? AND c.report_type='TRANSFERS' AND p.payload_type='TRANSFER_EVENT' AND CAST(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.player_id')) AS UNSIGNED)=? AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.club_from')),'')=? AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.club_to')),'')=? AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.amount_text')),'')=? AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(p.payload_json,'$.raw_row_text')),'')=? ORDER BY p.source_payload_id DESC LIMIT 1");
    $matches=[];foreach($candidates as $c){if(!is_array($c))continue;$pid=tr_uint($c['player_id']??null);if($pid===null)continue;$from=tr_text($c['club_from']??null,255)??'';$to=tr_text($c['club_to']??null,255)??'';$amount=tr_text($c['amount_text']??null,255)??'';$raw=tr_text($c['raw_row_text']??null,16777215)??'';$find->execute([$gw,$pid,$from,$to,$amount,$raw]);$r=$find->get_result()->fetch_assoc();if($r)$matches[]=['index'=>(int)($c['index']??0),'imcTransferNumber'=>(int)$r['n'],'playerId'=>$pid];}$find->close();
    ingestion_reply(['ok'=>true,'type'=>'transfers','action'=>'probe','repository'=>'gw_transfers','repositoryRows'=>$rows,'maxImcTransferNumber'=>$maxNumber,'matches'=>$matches]);
}
function tr_capture(mysqli $db,array $ctx,array $item): int {
    $page=(int)($item['source_page_number']??0);$signature=tr_text($item['source_page_signature']??null,255)??tr_hash($item['source_table_html']??'');$table=(string)($item['source_table_html']??'');$info=(string)($item['source_page_info_html']??'');$full=$table."\n".$info;
    $identity=tr_hash(['TRANSFERS',$ctx['game_world_id'],$page,$signature,tr_hash($full)]);$sourceSha=hash('sha256',$full);$captured=tr_text($item['source_captured_at']??null,40);$generated=null;if($captured!==null){try{$generated=(new DateTimeImmutable($captured))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d H:i:s.u');}catch(Throwable){$generated=null;}}
    $url=tr_text($item['source_url']??null,65535);$parts=$url?parse_url($url):[];$payload=tr_json(['type'=>'transfers','game_world_id'=>$ctx['game_world_id'],'page'=>$page,'page_signature'=>$signature]);$file='TRANSFERS_'.$ctx['game_world_id'].'_P'.$page.'_'.$identity.'.html';$pt=tr_page_type($db);
    $q=$db->prepare("INSERT INTO gw_source_captures(capture_json,capture_status,content_type,created_at,full_html,game_world_id,generated_at,hostname,language,origin,page_title,page_type_id,parser_version,pathname,ready_state,report_type,report_version,sm_game_world_id,source_file_name,source_file_sha256,source_identity_fingerprint,source_url,user_agent) VALUES(?,'COMPLETE','text/html',NOW(6),?,?,?,?,'it',?,?,?,?,?,'complete','TRANSFERS',?,?,?,?,?,?,NULL) ON DUPLICATE KEY UPDATE capture_id=LAST_INSERT_ID(capture_id),capture_json=VALUES(capture_json),full_html=VALUES(full_html),generated_at=COALESCE(VALUES(generated_at),generated_at),page_title=VALUES(page_title),source_url=VALUES(source_url)");
    $q->execute([$payload,$full,$ctx['game_world_id'],$generated,$parts['host']??null,isset($parts['scheme'],$parts['host'])?$parts['scheme'].'://'.$parts['host']:null,tr_text($item['source_title']??null,255),$pt,tr_text($item['version']??null,64),$parts['path']??null,tr_text($item['version']??null,32),$ctx['sm_game_world_id'],$file,$sourceSha,$identity,$url]);$id=(int)$db->insert_id;$q->close();if($id<1)ingestion_fail('TRANSFERS capture unavailable.',500);return $id;
}
function tr_world_club(mysqli $db,array $ctx,int $capture,?int $id,?string $name): ?int {
    if($id===null)return null;$q=$db->prepare('SELECT world_club_id,club_name FROM gw_world_clubs WHERE game_world_id=? AND world_club_id=? LIMIT 1');$q->execute([$ctx['game_world_id'],$id]);$r=$q->get_result()->fetch_assoc();$q->close();
    if($r)return $id;
    if($name===null)ingestion_fail('Native world club has no source name.',409);
    $q=$db->prepare('INSERT INTO gw_world_clubs(capture_id,club_name,created_at,game_world_id,master_club_id,sm_game_world_id,world_club_id) VALUES(?,?,NOW(6),?,NULL,?,?)');$q->execute([$capture,$name,$ctx['game_world_id'],$ctx['sm_game_world_id'],$id]);$q->close();return $id;
}
function tr_master_player(int $playerId): ?int {$core=smm_db();$q=$core->prepare('SELECT player_id FROM players WHERE player_id=? LIMIT 1');$q->execute([$playerId]);$r=$q->get_result()->fetch_assoc();$q->close();return $r?(int)$r['player_id']:null;}
function tr_send(mysqli $db,array $b,string $gw): never {
    $items=$b['items']??null;if(!is_array($items)||count($items)!==1||!is_array($items[0]))ingestion_fail('Exactly one TRANSFERS item required.');$item=$items[0];
    $player=tr_uint($item['player_id']??null);if($player===null)ingestion_fail('player_id required.');if(trim((string)($item['player_status_code']??''))!=='Com')ingestion_fail('Only exact Com rows are accepted.');
    $ctx=tr_core_world($gw);tr_ensure_world($db,$ctx);$rowOrder=tr_uint($item['source_row_order']??null);$page=tr_uint($item['source_page_number']??null);if($rowOrder===null||$page===null)ingestion_fail('Source page/row identity required.');
    $fromId=tr_uint($item['from_sm_world_club_id']??null);$toId=tr_uint($item['to_sm_world_club_id']??null);$fromName=tr_text($item['club_from']??null);$toName=tr_text($item['club_to']??null);$signature=tr_text($item['source_page_signature']??null,255);if($signature===null)ingestion_fail('source_page_signature required.');
    $stable=$item;unset($stable['source_captured_at'],$stable['imc_transfer_number']);$content=['player_id'=>$player,'from_world_club_id'=>$fromId,'from_name'=>$fromName,'to_world_club_id'=>$toId,'to_name'=>$toName,'cost_raw'=>tr_text($item['amount_text']??null),'status_code'=>'Com','status_title'=>tr_text($item['player_status_title']??null),'raw_row_text'=>tr_text($item['raw_row_text']??null,16777215)];
    $transferFp=tr_hash(['TRANSFERS',$gw,$signature,$page,$rowOrder,$content]);$eventFp=tr_hash(['TRANSFERS_EVENT',$gw,$signature,$page,$rowOrder,tr_hash($stable)]);$payload=tr_json($item);$payloadHash=tr_hash($payload);$importUuid=tr_text($b['importId']??null,36);$runId=null;
    if($importUuid!==null){$rq=$db->prepare('SELECT import_run_id FROM gw_import_runs WHERE run_uuid=? AND game_world_id=? LIMIT 1');$rq->execute([$importUuid,$gw]);$rr=$rq->get_result()->fetch_assoc();$rq->close();$runId=$rr?(int)$rr['import_run_id']:null;if($runId===null)ingestion_fail('TRANSFERS import run unavailable.',409);}
    try{$db->begin_transaction();$capture=tr_capture($db,$ctx,$item);$fromId=tr_world_club($db,$ctx,$capture,$fromId,$fromName);$toId=tr_world_club($db,$ctx,$capture,$toId,$toName);$master=tr_master_player($player);
        $pq=$db->prepare('INSERT INTO gw_players(created_at,first_seen_capture_id,game_world_id,last_seen_capture_id,master_player_id,player_id,sm_game_world_id) VALUES(NOW(6),?,?,?,?,?,?) ON DUPLICATE KEY UPDATE last_seen_capture_id=VALUES(last_seen_capture_id),master_player_id=COALESCE(master_player_id,VALUES(master_player_id)),sm_game_world_id=VALUES(sm_game_world_id)');$pq->execute([$capture,$gw,$capture,$master,$player,$ctx['sm_game_world_id']]);$pq->close();
        $find=$db->prepare('SELECT transfer_row_id FROM gw_transfers WHERE game_world_id=? AND transfer_fingerprint=? LIMIT 1');$find->execute([$gw,$transferFp]);$old=$find->get_result()->fetch_assoc();$find->close();$saved=0;$skipped=0;
        if($old){$skipped=1;}else{$ins=$db->prepare("INSERT INTO gw_transfers(capture_id,cost_numeric,cost_raw,created_at,currency,date,direction,event_fingerprint,from_club_name,from_world_club_id,game_world_id,gw_season_row_id,imc_season,player_id,player_value_at_event,raw_row_html,record_rank,sm_game_world_id,sm_season_id,soccer_manager_season,status,to_club_name,to_world_club_id,transfer_fingerprint,transfer_id) VALUES(?,?,?,NOW(6),NULL,NULL,NULL,?,?,?,?,NULL,NULL,?,?,?,NULL,?,NULL,NULL,'COMPLETED',?,?,?,NULL)");$ins->execute([$capture,tr_cost_number($item['amount_text']??null),tr_text($item['amount_text']??null),$eventFp,$fromName,$fromId,$gw,$player,tr_number($item['player_value_text']??null),$item['raw_row_html']??null,$ctx['sm_game_world_id'],$toName,$toId,$transferFp]);$ins->close();$saved=1;}
        $pf=tr_hash(['TRANSFER_EVENT',$transferFp]);$sp=$db->prepare("INSERT INTO gw_source_payloads(capture_id,created_at,payload_fingerprint,payload_hash,payload_json,payload_key,payload_text,payload_type) VALUES(?,NOW(6),?,?,?,?,?,'TRANSFER_EVENT') ON DUPLICATE KEY UPDATE payload_hash=VALUES(payload_hash),payload_json=VALUES(payload_json),payload_text=VALUES(payload_text)");$sp->execute([$capture,$pf,$payloadHash,$payload,(string)($item['imc_transfer_number']??''),$payload]);$sp->close();
        $summaryFp=tr_hash(['TRANSFER_SUMMARY',$gw,$signature]);$ss=$db->prepare('INSERT INTO gw_transfer_summary_snapshots(average_spent,capture_id,created_at,game_world_id,gw_season_row_id,imc_season,page_offset_or_turn,sm_game_world_id,sm_season_id,soccer_manager_season,total_count,total_spent,transfer_summary_fingerprint,world_club_id) VALUES(?,?,NOW(6),?,NULL,NULL,?,?,NULL,NULL,?,?,?,NULL) ON DUPLICATE KEY UPDATE average_spent=VALUES(average_spent),total_count=VALUES(total_count),total_spent=VALUES(total_spent)');$ss->execute([tr_number($item['source_avg_spent_text']??null),$capture,$gw,$page,$ctx['sm_game_world_id'],tr_uint($item['source_total_transfers']??null),tr_number($item['source_total_spent_text']??null),$summaryFp]);$ss->close();$db->commit();
        ingestion_reply(['ok'=>true,'type'=>'transfers','action'=>'send','savedThisSend'=>$saved,'skippedThisSend'=>$skipped,'transferFingerprint'=>$transferFp,'captureId'=>$capture,'playerResolved'=>$master!==null,'fromClubResolved'=>$fromId!==null,'toClubResolved'=>$toId!==null]);
    }catch(Throwable $e){try{$db->rollback();}catch(Throwable){}if($e instanceof InvalidArgumentException||$e instanceof RuntimeException)throw $e;ingestion_fail('TRANSFERS transaction failed: '.$e->getMessage(),500);}
}
function tr_finish(mysqli $db,array $b,string $gw): never {
    $uuid=tr_text($b['importId']??null,36);if($uuid===null)ingestion_fail('importId required.');$stats=['totalRowsRead'=>(int)($b['totalRowsRead']??0),'totalPages'=>(int)($b['totalPages']??0),'saved'=>(int)($b['saved']??0),'skipped'=>(int)($b['skipped']??0),'errors'=>(int)($b['errors']??0)];$sj=tr_json($stats);
    $q=$db->prepare("UPDATE gw_import_runs SET finished_at=NOW(6),run_status='success',source_capture_count=?,stats_json=? WHERE run_uuid=? AND game_world_id=?");$q->execute([$stats['totalPages'],$sj,$uuid,$gw]);if($q->affected_rows<1){$q->close();ingestion_fail('TRANSFERS import run unavailable.',409);}$q->close();$c=$db->prepare('SELECT COUNT(*) c FROM gw_transfers WHERE game_world_id=?');$c->execute([$gw]);$n=(int)$c->get_result()->fetch_assoc()['c'];$c->close();ingestion_reply(['ok'=>true,'type'=>'transfers','action'=>'finish','repositoryRows'=>$n]);
}
function tr_table_exists(mysqli $db,string $table): bool {$q=$db->prepare('SELECT COUNT(*) c FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$table]);$v=(int)$q->get_result()->fetch_assoc()['c'];$q->close();return $v===1;}
function tr_count(mysqli $db,string $sql,array $p=[]): int {$q=$db->prepare($sql);$q->execute($p);$v=(int)$q->get_result()->fetch_row()[0];$q->close();return $v;}
function tr_columns(mysqli $db,string $table,string $where,array $p): array {$cols=[];$q=$db->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? ORDER BY ORDINAL_POSITION');$q->execute([$table]);$rs=$q->get_result();while($r=$rs->fetch_assoc())$cols[]=$r['COLUMN_NAME'];$q->close();$out=[];foreach($cols as $c){$id='`'.str_replace('`','``',$c).'`';$out[$c]=['not_null'=>tr_count($db,"SELECT COUNT(*) FROM `$table` WHERE $where AND $id IS NOT NULL",$p),'null'=>tr_count($db,"SELECT COUNT(*) FROM `$table` WHERE $where AND $id IS NULL",$p)];}return $out;}
function tr_audit(mysqli $db,string $gw): never {
    $captures=tr_count($db,"SELECT COUNT(*) FROM gw_source_captures WHERE game_world_id=? AND report_type='TRANSFERS'",[$gw]);$payloads=tr_count($db,"SELECT COUNT(*) FROM gw_source_payloads p JOIN gw_source_captures c ON c.capture_id=p.capture_id WHERE c.game_world_id=? AND c.report_type='TRANSFERS' AND p.payload_type='TRANSFER_EVENT'",[$gw]);$persisted=tr_count($db,'SELECT COUNT(*) FROM gw_transfers WHERE game_world_id=?',[$gw]);$players=tr_count($db,'SELECT COUNT(DISTINCT player_id) FROM gw_transfers WHERE game_world_id=? AND player_id IS NOT NULL',[$gw]);
    $masterResolved=tr_count($db,'SELECT COUNT(DISTINCT t.player_id) FROM gw_transfers t JOIN gw_players p ON p.game_world_id=t.game_world_id AND p.player_id=t.player_id WHERE t.game_world_id=? AND p.master_player_id IS NOT NULL',[$gw]);
    $fromResolved=tr_count($db,'SELECT COUNT(*) FROM gw_transfers t JOIN gw_world_clubs c ON c.game_world_id=t.game_world_id AND c.world_club_id=t.from_world_club_id WHERE t.game_world_id=? AND t.from_world_club_id IS NOT NULL',[$gw]);$toResolved=tr_count($db,'SELECT COUNT(*) FROM gw_transfers t JOIN gw_world_clubs c ON c.game_world_id=t.game_world_id AND c.world_club_id=t.to_world_club_id WHERE t.game_world_id=? AND t.to_world_club_id IS NOT NULL',[$gw]);
    $duplicates=['transfer_fingerprint'=>tr_count($db,'SELECT COUNT(*) FROM (SELECT transfer_fingerprint FROM gw_transfers WHERE game_world_id=? GROUP BY transfer_fingerprint HAVING COUNT(*)>1) d',[$gw]),'event_fingerprint'=>tr_count($db,'SELECT COUNT(*) FROM (SELECT event_fingerprint FROM gw_transfers WHERE game_world_id=? GROUP BY event_fingerprint HAVING COUNT(*)>1) d',[$gw])];
    $orphans=['capture'=>tr_count($db,'SELECT COUNT(*) FROM gw_transfers t LEFT JOIN gw_source_captures c ON c.capture_id=t.capture_id WHERE t.game_world_id=? AND c.capture_id IS NULL',[$gw]),'season'=>tr_count($db,'SELECT COUNT(*) FROM gw_transfers t LEFT JOIN gw_seasons s ON s.gw_season_row_id=t.gw_season_row_id WHERE t.game_world_id=? AND t.gw_season_row_id IS NOT NULL AND s.gw_season_row_id IS NULL',[$gw]),'from_club'=>tr_count($db,'SELECT COUNT(*) FROM gw_transfers t LEFT JOIN gw_world_clubs c ON c.game_world_id=t.game_world_id AND c.world_club_id=t.from_world_club_id WHERE t.game_world_id=? AND t.from_world_club_id IS NOT NULL AND c.world_club_id IS NULL',[$gw]),'to_club'=>tr_count($db,'SELECT COUNT(*) FROM gw_transfers t LEFT JOIN gw_world_clubs c ON c.game_world_id=t.game_world_id AND c.world_club_id=t.to_world_club_id WHERE t.game_world_id=? AND t.to_world_club_id IS NOT NULL AND c.world_club_id IS NULL',[$gw])];
    $integrated=['player_codex_players'=>tr_count($db,"SELECT COUNT(DISTINCT t.player_id) FROM gw_transfers t JOIN gw_identity_matches m ON m.game_world_id=t.game_world_id AND m.local_id=CAST(t.player_id AS CHAR) AND m.entity_type='PLAYER' AND m.match_status='MATCHED' WHERE t.game_world_id=?",[$gw]),'fixture_world_clubs'=>tr_table_exists($db,'gw_fixtures')?tr_count($db,'SELECT COUNT(DISTINCT c.world_club_id) FROM gw_world_clubs c JOIN gw_fixtures f ON f.game_world_id=c.game_world_id AND (f.home_world_club_id=c.world_club_id OR f.away_world_club_id=c.world_club_id) WHERE c.game_world_id=? AND c.world_club_id IN (SELECT from_world_club_id FROM gw_transfers WHERE game_world_id=? UNION SELECT to_world_club_id FROM gw_transfers WHERE game_world_id=?)',[$gw,$gw,$gw]):0,'match_report_players'=>tr_table_exists($db,'gw_match_events')?tr_count($db,'SELECT COUNT(DISTINCT t.player_id) FROM gw_transfers t JOIN gw_match_events e ON e.game_world_id=t.game_world_id AND e.player_id=t.player_id WHERE t.game_world_id=?',[$gw]):0];
    $issues=tr_table_exists($db,'gw_import_issues')?tr_count($db,"SELECT COUNT(*) FROM gw_import_issues i JOIN gw_import_runs r ON r.import_run_id=i.import_run_id WHERE r.game_world_id=? AND r.parser_version LIKE 'IMC-TRANSFERS%'",[$gw]):0;
