function transfers_handle(mysqli $db,array $b,string $action,string $gw): never {
    if($action==='start')tr_start($db,$b,$gw);if($action==='probe')tr_probe($db,$b,$gw);if($action==='send')tr_send($db,$b,$gw);if($action==='finish')tr_finish($db,$b,$gw);if($action==='audit_transfers')tr_audit($db,$gw);ingestion_fail('Unknown transfers action.');
}
